sys_ui_page.client_script:
// 在UI Page的Client Script部分
function showConfirmation() {
    // 先阻止默认行为
    event.preventDefault();
    event.stopPropagation();

    var dialog = new GlideDialogWindow('confirm_dialog');
    dialog.setTitle('确认更新');
    dialog.setPreference('sys_id', g_form.getUniqueValue());
    dialog.setPreference('field_value', g_form.getValue('your_field'));
    dialog.setWidth(500);
    dialog.render();
}

// 处理确认结果的函数
function handleConfirmation(result, sys_id, fieldValue) {
    if (result === 'ok') {
        var ga = new GlideAjax('FieldUpdater');
        ga.addParam('sysparm_name', 'updateField');
        ga.addParam('sysparm_sys_id', sys_id);
        ga.addParam('sysparm_field_value', fieldValue);
        ga.getXML(function(response) {
            var answer = response.responseXML.documentElement.getAttribute("answer");
            if (answer === 'success') {
                g_form.addInfoMessage('字段更新成功！');
            } else {
                g_form.addErrorMessage('更新失败');
            }
        });
    }
}
